package com.shahboun.aqim;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.location.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;

public class WorldLocationActivity extends Activity{
 final int G=Color.rgb(15,76,58),GD=Color.rgb(205,168,92),I=Color.rgb(248,244,235),T=Color.rgb(35,48,43),M=Color.rgb(105,110,108);android.graphics.Typeface c;LinearLayout root;String selectedCountryCode,selectedCountryName;
 int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}GradientDrawable bg(int color,int r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(r));return g;}TextView tx(String s,int z,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setPadding(dp(7),dp(7),dp(7),dp(7));if(c!=null)t.setTypeface(c,bold?1:0);return t;}Button bt(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);b.setGravity(Gravity.CENTER);b.setTextColor(primary?Color.WHITE:T);b.setBackground(bg(primary?G:Color.WHITE,18));b.setElevation(dp(3));b.setMinHeight(0);b.setMinimumHeight(0);if(c!=null)b.setTypeface(c,1);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);try{if(Build.VERSION.SDK_INT>=26)c=getResources().getFont(getResources().getIdentifier("cairo","font",getPackageName()));}catch(Exception ignored){}show();}
 void show(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(16),dp(16),dp(16),dp(30));root.setBackgroundColor(I);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);root.addView(tx("الموقع",28,G,true));root.addView(tx("GPS هو الأساس. ويمكنك اختيار الدولة ثم المدينة يدويًا من القوائم بدون كتابة.",13,M,false));Button gps=bt("استخدام موقعي الحالي GPS",true);gps.setOnClickListener(v->gps());add(gps);Button country=bt(selectedCountryName==null?"اختيار الدولة":"الدولة: "+selectedCountryName,false);country.setOnClickListener(v->chooseCountry());add(country);Button city=bt("اختيار المدينة",false);city.setEnabled(selectedCountryCode!=null);city.setOnClickListener(v->chooseCity());add(city);SharedPreferences p=getSharedPreferences("aqim",0);root.addView(tx("الموقع المعتمد\n"+p.getString("city","طرابلس")+"\n"+p.getString("tzId","Africa/Tripoli"),15,T,true));ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(root);if(Build.VERSION.SDK_INT>=21)s.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets z=i.getInsets(WindowInsets.Type.systemBars());top=z.top;bottom=z.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return i;});setContentView(s);}
 void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58));p.setMargins(0,dp(7),0,0);root.addView(v,p);}
 void chooseCountry(){ArrayList<String> names=new ArrayList<>(),codes=new ArrayList<>();for(String code:Locale.getISOCountries()){Locale l=new Locale("",code);String n=l.getDisplayCountry(new Locale("ar"));if(n==null||n.trim().isEmpty())n=l.getDisplayCountry(Locale.ENGLISH);names.add(n);codes.add(code);}ArrayList<Integer> idx=new ArrayList<>();for(int i=0;i<names.size();i++)idx.add(i);Collections.sort(idx,(a,b)->names.get(a).compareTo(names.get(b)));LinearLayout box=dialogBase("اختر الدولة");EditText search=new EditText(this);search.setHint("بحث في الدول");search.setGravity(Gravity.CENTER);if(c!=null)search.setTypeface(c);box.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(list);box.addView(sc,new LinearLayout.LayoutParams(-1,dp(430)));Dialog d=new Dialog(this);Runnable render=()->{list.removeAllViews();String q=search.getText().toString().trim();for(int k:idx){String n=names.get(k);if(!q.isEmpty()&&!n.contains(q))continue;Button b=bt(n,false);b.setOnClickListener(v->{selectedCountryCode=codes.get(k);selectedCountryName=n;d.dismiss();show();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(2),0,dp(2));list.addView(b,p);}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int co,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();d.setContentView(box);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}}
 LinearLayout dialogBase(String title){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(14),dp(14),dp(14),dp(14));b.setBackground(bg(I,22));b.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);b.addView(tx(title,22,G,true));return b;}
 void chooseCity(){if(selectedCountryCode==null)return;LinkedHashMap<String,String> cities=new LinkedHashMap<>();try{String[] zones=Build.VERSION.SDK_INT>=24?android.icu.util.TimeZone.getAvailableIDs(selectedCountryCode):new String[0];for(String z:zones){if(!z.contains("/"))continue;String n=z.substring(z.lastIndexOf('/')+1).replace('_',' ');cities.put(n,z);}}catch(Exception ignored){}try{Geocoder g=new Geocoder(this,new Locale("ar"));List<Address>a=g.getFromLocationName(selectedCountryName,40);if(a!=null)for(Address x:a){String n=x.getLocality()!=null?x.getLocality():x.getSubAdminArea()!=null?x.getSubAdminArea():x.getAdminArea();if(n!=null&&!n.trim().isEmpty())cities.put(n,chooseZone(selectedCountryCode,x.getLongitude()));}}catch(Exception ignored){}if(cities.isEmpty()){Toast.makeText(this,"لم تتوفر مدن تلقائيًا لهذه الدولة. استخدم GPS للموقع الأدق.",Toast.LENGTH_LONG).show();return;}ArrayList<String> names=new ArrayList<>(cities.keySet());Collections.sort(names);LinearLayout box=dialogBase("اختر المدينة • "+selectedCountryName);EditText search=new EditText(this);search.setHint("بحث في المدن");search.setGravity(Gravity.CENTER);if(c!=null)search.setTypeface(c);box.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sc=new ScrollView(this);sc.addView(list);box.addView(sc,new LinearLayout.LayoutParams(-1,dp(430)));Dialog d=new Dialog(this);Runnable render=()->{list.removeAllViews();String q=search.getText().toString().trim();for(String n:names){if(!q.isEmpty()&&!n.contains(q))continue;Button b=bt(n,false);b.setOnClickListener(v->{resolveCity(n,cities.get(n));d.dismiss();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.setMargins(0,dp(2),0,dp(2));list.addView(b,p);}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int co,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();d.setContentView(box);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}}
 void resolveCity(String city,String tz){try{Geocoder g=new Geocoder(this,Locale.getDefault());List<Address>a=g.getFromLocationName(city+", "+selectedCountryName,3);if(a!=null&&!a.isEmpty()){Address x=a.get(0);save(city+" • "+selectedCountryName,x.getLatitude(),x.getLongitude(),tz);return;}}catch(Exception ignored){}try{java.util.TimeZone z=java.util.TimeZone.getTimeZone(tz);double lon=z.getRawOffset()/3600000.0*15.0;save(city+" • "+selectedCountryName,0,lon,tz);}catch(Exception e){Toast.makeText(this,"استخدم GPS للحصول على إحداثيات دقيقة",Toast.LENGTH_LONG).show();}}
 void gps(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},91);return;}try{LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;for(String p:lm.getProviders(true)){Location l=lm.getLastKnownLocation(p);if(l!=null&&(best==null||l.getAccuracy()<best.getAccuracy()))best=l;}if(best==null){Toast.makeText(this,"فعّل GPS ثم حاول مجددًا",Toast.LENGTH_LONG).show();return;}String name="GPS";String cc=null;try{List<Address>a=new Geocoder(this,Locale.getDefault()).getFromLocation(best.getLatitude(),best.getLongitude(),1);if(a!=null&&!a.isEmpty()){Address x=a.get(0);name=(x.getLocality()!=null?x.getLocality():x.getAdminArea()!=null?x.getAdminArea():x.getCountryName());cc=x.getCountryCode();}}catch(Exception ignored){}save(name,best.getLatitude(),best.getLongitude(),chooseZone(cc,best.getLongitude()));}catch(Exception e){Toast.makeText(this,"تعذر تحديد الموقع",Toast.LENGTH_LONG).show();}}
 String chooseZone(String cc,double lon){try{if(cc!=null&&Build.VERSION.SDK_INT>=24){String[] ids=android.icu.util.TimeZone.getAvailableIDs(cc.toUpperCase(Locale.US));if(ids!=null&&ids.length>0){long now=System.currentTimeMillis();double solar=lon/15.0;String best=ids[0];double score=999;for(String id:ids){java.util.TimeZone z=java.util.TimeZone.getTimeZone(id);double off=z.getOffset(now)/3600000.0,s=Math.abs(off-solar);if(s<score){score=s;best=id;}}return best;}}}catch(Exception ignored){}return java.util.TimeZone.getDefault().getID();}
 void save(String name,double lat,double lon,String tz){getSharedPreferences("aqim",0).edit().putString("city",name).putFloat("lat",(float)lat).putFloat("lon",(float)lon).putString("tzId",tz).apply();MainActivity.scheduleAll(this);PrayerWidget.updateAll(this);Toast.makeText(this,"تم اعتماد "+name,Toast.LENGTH_LONG).show();show();}
 @Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==91&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)gps();}
}
